pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Ensure target is not the contract itself (to avoid recursion) and is not zero (EOA)
        vm.assume(target != address(c));
        vm.assume(target != address(0));
        // Ensure target is an EOA (no code)
        vm.assume(target.code.length == 0);
        // Bound value to avoid out-of-gas issues
        value = bound(value, 0, 100 ether);

        // Get initial depositsCount
        uint256 initialDeposits = c.depositsCount();

        // Fund the contract so it can send ether
        vm.deal(address(c), 1000 ether);

        // Call sendMoney
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value));
        // Must succeed since owner sends to EOA
        assertTrue(success);

        // Check that depositsCount remained the same
        assertTrue(c.depositsCount() == initialDeposits);
    }
}

