        // Ensure the target is an EOA (no code) so the fallback does not trigger
        vm.assume(target.code.length == 0);
        // Store the depositsCount before the sendMoney call
        uint256 countBefore = c.depositsCount();
        // Attempt to send ETH via sendMoney
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));
        // The call should always succeed (no revert) for EOA targets
        assertTrue(ok, "sendMoney should not revert when sending to EOA");
        // After the transfer, depositsCount must remain unchanged
        assertTrue(c.depositsCount() == countBefore, "depositsCount should not change when sendMoney targets an EOA");
    }
}

