pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        value = bound(value, 1, address(this).balance);
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;
        // The reference C will revert if the call fails, so we wrap in try/catch
        try c.sendMoney(target, value) {
            // If it doesn't revert, then balance should not change (since require(!__sent_result100) would fail on success)
        } catch {}
        assertTrue(address(c).balance == balanceBefore);
    }
}

